    /// <summary>
    /// Sells a gift for Telegram Stars; requires owner privileges for gifts owned by a chat
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SellGiftAsync(string businessConnectionId = default, string receivedGiftId = default)
    {

           using var activity =  StartCallActivity("SellGiftAsync", typeof(SellGift).FullName ?? "SellGiftAsync");

           try
           {
             return client.SellGiftAsync(businessConnectionId, receivedGiftId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
